    if (State.currentUser) {
        actionCallback();
    } else {
        showToast("Please sign in or register to proceed", "error");
        pendingAuthCallback = actionCallback;

        // Hide detail modal if it's currently open to avoid overlapping flex cards
        if (!DOM.modalDetail.classList.contains('hidden')) {
            State.modalDetailWasOpen = true;
            DOM.modalDetail.classList.add('hidden');
        }

        openAuthModal('signin');
    }
}"

