/* Hero Text & Slide Entry Animations */
.carousel-item.active .hero-title {
    animation: fadeInUp 0.85s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.carousel-item.active .hero-subtext {
    animation: fadeInUp 0.85s 0.18s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.carousel-item.active .hero-action {
    animation: fadeInUp 0.85s 0.36s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(28px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

