"    // Scroll Reveal Observer for Sections & Cards (including Why Havora Dropping Text)
    const revealElements = document.querySelectorAll('.platform-card, .stand-card, .how-card, .section-header, .why-havora-section');
    revealElements.forEach(el => el.classList.add('reveal-on-scroll'));

    if ('IntersectionObserver' in window) {
        const revealObserver = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('animated-in');
                    observer.unobserve(entry.target);
                }
            });
        }, { threshold: 0.12 });

        revealElements.forEach(el => revealObserver.observe(el));
    } else {
        revealElements.forEach(el => el.classList.add('animated-in'));
    }"

